  ('player', 'TR Counter Squad', 'YOUR TEAM', 'player', 'champions_reg_m_doubles_bo3', 'builtin', 'player_champions_speed_v1', 'Fast offensive pressure with Intimidate + Will-O-Wisp support. Built to break Trick Room before it starts.', '{"assumption_register":["This remains a user-authored starter team, not a pinned event export.","The original anti-Trick-Room shell was preserved while converting its spreads to Champions SP scale."],"champion_pack_id":"player_champions_speed_v1","format":"champions","formatid":"champions-vgc-2026-regma","gametype":"doubles","legality_notes":"Champion testing anti-Trick-Room starter. Moves, items, and Champions SP spreads are pinned to the current Showdown-backed legality gate; this is not an exact tournament export.","legality_status":"legal","provenance":{"author":"user","roster_source":"user-authored","spread_source":"user-authored","status":"testing_archetype","url":""},"ruleset":["Species Clause","Item Clause","Bring 6 Pick 4","Level 50"],"style":"speed"}'::jsonb),
